+pub fn paint_text(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+) -> Result<(), Error> {
+    paint_text_scaled(pixels, stride, x, y, text, color, 1)
+}
+
+pub fn paint_text_scaled(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+    scale: u16,
+) -> Result<(), Error> {
+    if stride == 0 || !pixels.len().is_multiple_of(stride) {
+        return Err(Error::Bounds);
+    }
+    if scale == 0 || scale > 4 {
+        return Err(Error::Bounds);
+    }
+    let width = u16::try_from(stride).map_err(|_| Error::Bounds)?;
+    let height = u16::try_from(pixels.len() / stride).map_err(|_| Error::Bounds)?;
+    let clip = Rect::new(0, 0, width, height);
+    let scale = scale as i16;
+    for (index, byte) in text.iter().enumerate() {
+        let ox = x + index as i16 * 4 * scale;
+        for row in 0..5_i16 {
+            let bits = glyph(*byte)[row as usize];
+            for column in 0..3_i16 {
+                if bits & (1 << (2 - column)) != 0 {
+                    fill(
+                        pixels,
+                        stride,
+                        Rect::new(
+                            ox + column * scale,
+                            y + row * scale,
+                            scale as u16,
+                            scale as u16,
+                        ),
+                        color,
+                        clip,
+                    );
+                }
+            }
+        }
+    }
+    Ok(())
+}
+
+pub fn paint_text_5x7_scaled(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+    scale: u16,
+) -> Result<(), Error> {
+    if stride == 0 || !pixels.len().is_multiple_of(stride) || scale == 0 || scale > 4 {
+        return Err(Error::Bounds);
+    }
+    let width = u16::try_from(stride).map_err(|_| Error::Bounds)?;
+    let height = u16::try_from(pixels.len() / stride).map_err(|_| Error::Bounds)?;
+    let clip = Rect::new(0, 0, width, height);
+    let scale = scale as i16;
+    for (index, byte) in text.iter().copied().enumerate() {
+        let ox = x + index as i16 * 6 * scale;
+        for (row, bits) in glyph_5x7(byte).into_iter().enumerate() {
+            for column in 0..5_i16 {
+                if bits & (1 << (4 - column)) != 0 {
+                    fill(
+                        pixels,
+                        stride,
+                        Rect::new(
+                            ox + column * scale,
+                            y + row as i16 * scale,
+                            scale as u16,
+                            scale as u16,
+                        ),
+                        color,
+                        clip,
+                    );
+                }
+            }
+        }
+    }
+    Ok(())
+}
