+/// Paint the compact 5x7 face with softened exposed corners. This keeps the
+/// renderer allocation-free while avoiding the blocky appearance of a raw
+/// nearest-neighbour scale at normal controller UI sizes.
+pub fn paint_text_5x7_smooth(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+) -> Result<(), Error> {
+    if stride == 0 || !pixels.len().is_multiple_of(stride) {
+        return Err(Error::Bounds);
+    }
+    let width = i32::try_from(stride).map_err(|_| Error::Bounds)?;
+    let height = i32::try_from(pixels.len() / stride).map_err(|_| Error::Bounds)?;
+    for (index, byte) in text.iter().copied().enumerate() {
+        let glyph = glyph_5x7(byte);
+        let origin_x = i32::from(x) + index as i32 * 12;
+        let origin_y = i32::from(y);
+        for row in 0..7_usize {
+            for column in 0..5_usize {
+                if glyph[row] & (1 << (4 - column)) == 0 {
+                    continue;
+                }
+                let left = column != 0 && glyph[row] & (1 << (5 - column)) != 0;
+                let right = column != 4 && glyph[row] & (1 << (3 - column)) != 0;
+                let above = row != 0 && glyph[row - 1] & (1 << (4 - column)) != 0;
+                let below = row != 6 && glyph[row + 1] & (1 << (4 - column)) != 0;
+                for dy in 0..2_i32 {
+                    for dx in 0..2_i32 {
+                        let px = origin_x + column as i32 * 2 + dx;
+                        let py = origin_y + row as i32 * 2 + dy;
+                        if px < 0 || py < 0 || px >= width || py >= height {
+                            continue;
+                        }
+                        let soften = match (dx, dy) {
+                            (0, 0) => !left && !above,
+                            (1, 0) => !right && !above,
+                            (0, 1) => !left && !below,
+                            _ => !right && !below,
+                        };
+                        let slot = py as usize * stride + px as usize;
+                        pixels[slot] = if soften {
+                            blend_rgb(pixels[slot], color, 3, 4)
+                        } else {
+                            color
+                        };
+                    }
+                }
+            }
+        }
+    }
+    Ok(())
+}
+
+/// Paint the embedded antialiased Inter controller face. The atlas is
+/// generated ahead of time so the freestanding renderer needs neither a font
+/// parser nor allocation at runtime.
+struct FontAtlas {
+    first: u8,
+    last: u8,
+    width: usize,
+    height: usize,
+    advance: &'static [u8],
+    alpha_4: &'static [u8],
+}
+
+const INTER_13: FontAtlas = FontAtlas {
+    first: inter_13::GLYPH_FIRST,
+    last: inter_13::GLYPH_LAST,
+    width: inter_13::GLYPH_WIDTH,
+    height: inter_13::GLYPH_HEIGHT,
+    advance: &inter_13::GLYPH_ADVANCE,
+    alpha_4: &inter_13::GLYPH_ALPHA_4,
+};
+
+const INTER_16: FontAtlas = FontAtlas {
+    first: inter_16::GLYPH_FIRST,
+    last: inter_16::GLYPH_LAST,
+    width: inter_16::GLYPH_WIDTH,
+    height: inter_16::GLYPH_HEIGHT,
+    advance: &inter_16::GLYPH_ADVANCE,
+    alpha_4: &inter_16::GLYPH_ALPHA_4,
+};
+
+fn paint_text_atlas(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+    atlas: &FontAtlas,
+) -> Result<(), Error> {
+    if stride == 0 || !pixels.len().is_multiple_of(stride) {
+        return Err(Error::Bounds);
+    }
+    let width = i32::try_from(stride).map_err(|_| Error::Bounds)?;
+    let height = i32::try_from(pixels.len() / stride).map_err(|_| Error::Bounds)?;
+    let mut origin_x = i32::from(x);
+    let origin_y = i32::from(y);
+    for byte in text.iter().copied() {
+        let byte = if (atlas.first..=atlas.last).contains(&byte) {
+            byte
+        } else {
+            b'?'
+        };
+        let glyph = usize::from(byte - atlas.first);
+        let glyph_start = glyph * atlas.width * atlas.height;
+        for row in 0..atlas.height {
+            let py = origin_y + row as i32;
+            if py < 0 || py >= height {
+                continue;
+            }
+            for column in 0..atlas.width {
+                let px = origin_x + column as i32;
+                if px < 0 || px >= width {
+                    continue;
+                }
+                let alpha_index = glyph_start + row * atlas.width + column;
+                let packed = atlas.alpha_4[alpha_index / 2];
+                let alpha = u32::from(if alpha_index.is_multiple_of(2) {
+                    packed >> 4
+                } else {
+                    packed & 0x0f
+                }) * 17;
+                if alpha == 0 {
+                    continue;
+                }
+                let slot = py as usize * stride + px as usize;
+                pixels[slot] = if alpha == 255 {
+                    color
+                } else {
+                    blend_rgb(pixels[slot], color, alpha, 255)
+                };
+            }
+        }
+        origin_x += i32::from(atlas.advance[glyph]);
+    }
+    Ok(())
+}
+
+/// Paint compact body text for the 1024 by 768 controller shell.
+pub fn paint_text_inter_13(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+) -> Result<(), Error> {
+    paint_text_atlas(pixels, stride, x, y, text, color, &INTER_13)
+}
+
+/// Paint the larger heading face used sparingly for visual hierarchy.
+pub fn paint_text_inter_16(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+) -> Result<(), Error> {
+    paint_text_atlas(pixels, stride, x, y, text, color, &INTER_16)
+}
+
+fn blend_rgb(background: u32, foreground: u32, numerator: u32, denominator: u32) -> u32 {
+    let blend = |shift| {
+        let background = (background >> shift) & 0xff_u32;
+        let foreground = (foreground >> shift) & 0xff_u32;
+        (background * (denominator - numerator) + foreground * numerator) / denominator
+    };
+    (blend(16) << 16) | (blend(8) << 8) | blend(0)
+}
