+fn draw_text(
+    pixels: &mut [u32],
+    stride: usize,
+    x: i16,
+    y: i16,
+    text: &[u8],
+    color: u32,
+    clip: Rect,
+) {
+    for (index, byte) in text.iter().enumerate() {
+        let ox = x + (index as i16 * 4);
+        for row in 0..5_i16 {
+            let bits = glyph(*byte)[row as usize];
+            for column in 0..3_i16 {
+                if bits & (1 << (2 - column)) != 0 {
+                    fill(
+                        pixels,
+                        stride,
+                        Rect::new(ox + column, y + row, 1, 1),
+                        color,
+                        clip,
+                    );
+                }
+            }
+        }
+    }
+}
+
+fn glyph(byte: u8) -> [u8; 5] {
