+pub fn pixel_hash(pixels: &[u32]) -> u64 {
+    pixels.iter().fold(0xcbf2_9ce4_8422_2325, |hash, pixel| {
+        (hash ^ u64::from(*pixel)).wrapping_mul(0x100_0000_01b3)
+    })
+}
