+        let _ = self.inject(
+            ginux_native_abi::NATIVE_INPUT_KIND_KEY,
+            u32::from(code),
+            if released { 0 } else { 1 },
+        );
+        (!released).then(|| set1_ascii(code, self.shift)).flatten()
+    }
+
+    fn mouse(&mut self, byte: u8) -> bool {
+        if self.mouse_length == 0 && byte & 0x08 == 0 {
+            return false;
+        }
+        self.mouse_packet[usize::from(self.mouse_length)] = byte;
+        self.mouse_length += 1;
+        if self.mouse_length != 3 {
+            return false;
+        }
+        self.mouse_length = 0;
+        let dx = i16::from(self.mouse_packet[1] as i8);
+        let dy = -i16::from(self.mouse_packet[2] as i8);
+        let max_x = self.framebuffer.map_or(399, |framebuffer| {
+            framebuffer.width.saturating_sub(1) as i16
+        });
+        let max_y = self.framebuffer.map_or(299, |framebuffer| {
+            framebuffer.height.saturating_sub(1) as i16
+        });
+        self.pointer_x = (self.pointer_x + dx).clamp(0, max_x);
+        self.pointer_y = (self.pointer_y + dy).clamp(0, max_y);
+        if dx != 0 || dy != 0 {
+            let _ = self.inject(
+                ginux_native_abi::NATIVE_INPUT_KIND_POINTER_MOTION,
+                u32::from(self.pointer_x as u16) | (u32::from(self.pointer_y as u16) << 16),
+                (i32::from(dx) & 0xffff) | (i32::from(dy) << 16),
+            );
+        }
+        let buttons = self.mouse_packet[0] & 0x07;
+        let changed = self.buttons ^ buttons;
+        if changed != 0 {
+            self.buttons = buttons;
+            let _ = self.inject(
+                ginux_native_abi::NATIVE_INPUT_KIND_POINTER_BUTTON,
+                u32::from(changed),
+                i32::from(buttons),
+            );
+        }
+        true
+    }
+}
