+pub(crate) fn hardware_input_ready() -> bool {
+    in_u8(0x64) & 0x01 != 0
+}
+
+pub(crate) fn read_hardware_input() -> Option<u8> {
+    if !hardware_input_ready() {
+        return None;
+    }
+    let status = in_u8(0x64);
+    let byte = in_u8(0x60);
+    let mut devices = DEVICES.lock();
+    if status & 0x20 != 0 {
+        devices.mouse(byte).then_some(0)
+    } else {
+        devices.keyboard(byte)
+    }
+}
+
+pub(crate) fn initialize_hardware_input() -> bool {
+    for _ in 0..32 {
+        if !hardware_input_ready() {
+            break;
+        }
+        let _ = in_u8(0x60);
+    }
+    if wait_input_clear() {
+        out_u8(0x64, 0x20);
+    }
+    let configuration = wait_output_ready().map(|value| (value | 0x40) & !0x30);
+    if let Some(configuration) = configuration {
+        if wait_input_clear() {
+            out_u8(0x64, 0x60);
+        }
+        if wait_input_clear() {
+            out_u8(0x60, configuration);
+        }
+    }
+    if wait_input_clear() {
+        out_u8(0x64, 0xae);
+    }
+    let keyboard_reset = write_keyboard(0xff) && wait_output_ready() == Some(0xaa);
+    let keyboard_enabled =
+        keyboard_reset && write_keyboard(0xf0) && write_keyboard(0x02) && write_keyboard(0xf4);
+    if wait_input_clear() {
+        out_u8(0x64, 0xa8);
+    }
+    // Use the highest standard PS/2 reporting rate. QEMU otherwise defaults
+    // to 100 Hz, which is visibly coarse on a native software cursor.
+    let mouse_enabled = write_mouse(0xf3) && write_mouse(200) && write_mouse(0xf4);
+    keyboard_enabled && mouse_enabled
+}
+
+fn write_keyboard(command: u8) -> bool {
+    if !wait_input_clear() {
+        return false;
+    }
+    out_u8(0x60, command);
+    wait_output_ready() == Some(0xfa)
+}
+
+fn write_mouse(command: u8) -> bool {
+    if !wait_input_clear() {
+        return false;
+    }
+    out_u8(0x64, 0xd4);
+    if !wait_input_clear() {
+        return false;
+    }
+    out_u8(0x60, command);
+    wait_output_ready() == Some(0xfa)
+}
+
+fn wait_output_ready() -> Option<u8> {
+    for _ in 0..100_000 {
+        if in_u8(0x64) & 0x01 != 0 {
+            return Some(in_u8(0x60));
+        }
+        core::hint::spin_loop();
+    }
+    None
+}
+
+fn wait_input_clear() -> bool {
+    for _ in 0..100_000 {
+        if in_u8(0x64) & 0x02 == 0 {
+            return true;
+        }
+        core::hint::spin_loop();
+    }
+    false
+}
