+fn set1_ascii(code: u8, shift: bool) -> Option<u8> {
+    let plain = match code {
+        0x02..=0x0a => b'1' + code - 0x02,
+        0x0b => b'0',
+        0x0c => b'-',
+        0x0e => 0x08,
+        0x0f => b'\t',
+        0x10 => b'q',
+        0x11 => b'w',
+        0x12 => b'e',
+        0x13 => b'r',
+        0x14 => b't',
+        0x15 => b'y',
+        0x16 => b'u',
+        0x17 => b'i',
+        0x18 => b'o',
+        0x19 => b'p',
+        0x1c => b'\n',
+        0x1e => b'a',
+        0x1f => b's',
+        0x20 => b'd',
+        0x21 => b'f',
+        0x22 => b'g',
+        0x23 => b'h',
+        0x24 => b'j',
+        0x25 => b'k',
+        0x26 => b'l',
+        0x2c => b'z',
+        0x2d => b'x',
+        0x2e => b'c',
+        0x2f => b'v',
+        0x30 => b'b',
+        0x31 => b'n',
+        0x32 => b'm',
+        0x39 => b' ',
+        _ => return None,
+    };
+    Some(if shift && plain.is_ascii_lowercase() {
+        plain.to_ascii_uppercase()
+    } else {
+        plain
+    })
+}
