+}
+
+fn exit(status: u8) -> ! {
+    unsafe {
+        asm!(
+            "int 0x80",
+            in("rax") NATIVE_SERVICE_EXIT_OPERATION,
+            in("rdi") 0_u64,
+            in("rsi") u64::from(status),
+            options(noreturn),
+        );
+    }
+}
+
+fn fail() -> ! {
+    unsafe { asm!("int3", options(noreturn)) }
+}

